const baseUrl = pm.environment.get("baseUrl");
const sourceId = pm.environment.get("accountId");
const targetId = pm.environment.get("toAccountId");
const amount = Number(pm.environment.get("transferAmount"));

const sourceBefore = Number(
    pm.environment.get("sourceBalanceBefore")
);
const targetBefore = Number(
    pm.environment.get("targetBalanceBefore")
);

pm.test("Starting balances are available", function () {
    pm.expect(Number.isFinite(sourceBefore)).to.eql(true);
    pm.expect(Number.isFinite(targetBefore)).to.eql(true);
    pm.expect(Number.isFinite(amount)).to.eql(true);
});

if (
    pm.response.code === 200 &&
    Number.isFinite(sourceBefore) &&
    Number.isFinite(targetBefore) &&
    Number.isFinite(amount)
) {
    pm.sendRequest({
        url: `${baseUrl}/accounts/${sourceId}`,
        method: "GET",
        header: { Accept: "application/json" }
    }, function (err, response) {
        pm.test("Source account balance reflects the transfer", function () {
            pm.expect(err).to.eql(null);
            pm.expect(response.code).to.eql(200);

            const account = response.json();
            pm.expect(Number(account.balance))
                .to.be.closeTo(sourceBefore - amount, 0.01);
        });
    });

    pm.sendRequest({
        url: `${baseUrl}/accounts/${targetId}`,
        method: "GET",
        header: { Accept: "application/json" }
    }, function (err, response) {
        pm.test("Target account balance reflects the transfer", function () {
            pm.expect(err).to.eql(null);
            pm.expect(response.code).to.eql(200);

            const account = response.json();
            pm.expect(Number(account.balance))
                .to.be.closeTo(targetBefore + amount, 0.01);
        });
    });
}

pm.test("HTTP status is 200", function () {
    pm.response.to.have.status(200);
});

const transactions = pm.response.json();
const accountId = Number(pm.environment.get("accountId"));

pm.test("Response contains a transaction list", function () {
    pm.expect(transactions).to.be.an("array");
});

pm.test("Transaction records contain the required fields", function () {
    pm.expect(transactions.length).to.be.above(0);

    transactions.forEach(transaction => {
        pm.expect(transaction).to.have.property("id");
        pm.expect(transaction).to.have.property("accountId");
        pm.expect(transaction).to.have.property("type");
        pm.expect(transaction).to.have.property("date");
        pm.expect(transaction).to.have.property("amount");
        pm.expect(transaction).to.have.property("description");
    });
});

pm.test("All transactions belong to the requested account", function () {
    transactions.forEach(transaction => {
        pm.expect(Number(transaction.accountId)).to.eql(accountId);
    });
});

pm.test("Transaction types and amounts are valid", function () {
    transactions.forEach(transaction => {
        pm.expect(transaction.type).to.be.oneOf(["Credit", "Debit"]);
        pm.expect(Number(transaction.amount)).to.be.a("number");
        pm.expect(Number.isFinite(Number(transaction.amount))).to.eql(true);
        pm.expect(Number(transaction.date)).to.be.above(0);
        pm.expect(transaction.description).to.be.a("string").and.not.empty;
    });
});

